# area: dunder_dispatch
# hypothesis: len() and call() use dunders from the type, so an instance-assigned __len__ is ignored and an annotation-only __call__ raises TypeError at runtime, while __getattr__ does not serve implicit dunder lookups.
from collections.abc import Callable
from typing import reveal_type


class Bag:
    def __init__(self, items: list[int]) -> None:
        self.items = items
        self.__len__ = lambda: 99  # instance attribute, never used by len()

    def __getattr__(self, name: str) -> str:
        return 'fallback:' + name

    def __getitem__(self, i: int) -> int:
        return self.items[i]


class Hook:
    __call__: Callable[[int], int]  # annotation only, no runtime method


def try_len(b: Bag) -> str:
    try:
        return str(len(b))  # expect-error: Bag has no __len__ on its type
    except TypeError:
        return 'TypeError'


def try_call(h: Hook) -> str:
    try:
        return str(h(3))
    except TypeError:
        return 'TypeError'


bag = Bag([4, 5])
reveal_type(bag[0])
reveal_type(bag.missing)
print(bag.__len__(), bag.__getattr__('x'), bag[1])
print(try_len(bag))
print(try_call(Hook()))
